INSERT INTO `product_categories` VALUES (1,'Metal Deck Klips','metal-deck-klips','Paslanmaz çelik ve metal alaşımlı profesyonel deck klips sistemleri','',1,'active','🔩','2026-04-04 20:43:01','2026-04-24 16:54:30','Metal Deck Clips','مشابك ديسك معدنية','Premium stainless steel and galvanized metal clips.','مشابك معدنية مجلفنة وعالية الجودة.','',''),(2,'Plastik Deck Klips','plastik-deck-klips','UV dayanımlı yüksek performanslı plastik deck klips sistemleri','',2,'active','🪣','2026-04-04 20:43:01','2026-04-24 16:54:30','Plastic Deck Clips','مشابك ديسك بلاستيكية','UV-resistant high-quality plastic clips.','مشابك بلاستيكية مقاومة للأشعة فوق البنفسجية.','',''),(3,'Cam Balkon Aksesuarları','cam-balkon-aksesuarlari','Cam Balkon Aksesuarları','',3,'active','','2026-05-14 21:09:45','2026-05-14 22:07:45','Glass Balcony Accessories','إكسسوارات الشرفات الزجاجية',NULL,NULL,'glass-balcony-accessories','اكسسوارات-الشرفات-الزجاجية');
