DROP TABLE IF EXISTS `product_translations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `product_translations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL,
  `lang_code` varchar(10) NOT NULL,
  `name` varchar(255) NOT NULL,
  `short_description` varchar(500) DEFAULT NULL,
  `long_description` text DEFAULT NULL,
  `specifications` text DEFAULT NULL,
  `features` text DEFAULT NULL,
  `seo_title` varchar(255) DEFAULT '',
  `seo_description` text DEFAULT NULL,
  `seo_keywords` varchar(500) DEFAULT '',
  `faq_json` text DEFAULT NULL,
  `howto_json` text DEFAULT NULL,
  `slug` varchar(255) DEFAULT NULL,
  `faq_title` varchar(255) DEFAULT NULL,
  `howto_title` varchar(255) DEFAULT NULL,
  `price_quantity` varchar(50) DEFAULT '',
  `series_label` varchar(100) DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_product_lang` (`product_id`,`lang_code`),
  CONSTRAINT `product_translations_ibfk_1` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=588 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

