INSERT INTO `product_translations` VALUES (18,3,'tr','Gizli Montaj Deck Klipsi','Ahşap ve kompozit deck panellerde görünmez montaj sağlayan plastik klips montaj sistemi.','Gizli Montaj Deck Klipsi, ahşap ve kompozit deck uygulamalarında vidaların görünmesini istemeyen profesyoneller için tasarlanmıştır. Kullanım amacına uygun plastikten üretilen deck klips uzun ömürlü kullanım sunar.\r\n\r\nDeck panellerinin arasına gizlenen özel tasarımı sayesinde estetik bir yüzey elde edilir. Kolay montajı ile işçilik süresini kısaltır.\r\n\r\nHem iç hem dış mekan uygulamalarında güvenle kullanılabilir. ','Malzeme: Plastik\r\nBoyut: Görselde inceleyiniz.\r\nUyumlu Deck Kalınlığı: 18-25mm\r\nPaket: 1000 adet/kutu\r\n','Gizli montaj sistemi\r\nPlastik yapı\r\nKolay kurulum\r\nStandart deck tiplerine uyumlu','','','Deck Klips, Deck Klips Plastik',NULL,NULL,NULL,NULL,NULL,'',''),(19,3,'en','Hidden Mounting Deck Clip','Plastic clip mounting system providing invisible installation for wood and composite deck panels.','The Hidden Mounting Deck Clip is designed for professionals who prefer not to have screws visible in wood and composite deck applications. Made from durable plastic for its intended use, this deck clip offers long-lasting performance.<br><br>\r\n\r\nIts unique design, concealed between deck panels, ensures an aesthetic surface. Easy installation reduces labor time.<br><br>\r\n\r\nSuitable for both indoor and outdoor applications with confidence.','Material: Plastic<br>Size: Refer to the image.<br>Compatible Deck Thickness: 18-25mm<br>Package: 1000 units/box','Hidden mounting system<br>Plastic construction<br>Easy installation<br>Compatible with standard deck types','','','Deck Clip, Plastic Deck Clip',NULL,NULL,NULL,NULL,NULL,'',''),(20,3,'ar','كليب تثبيت الديك الخفي','نظام تثبيت كليب بلاستيكي يوفر تركيباً غير مرئي لألواح الديك الخشبية والمركبة.','تم تصميم كليب تثبيت الديك الخفي للمحترفين الذين لا يرغبون في ظهور البراغي في تطبيقات الديك الخشبية والمركبة. يُصنع كليب الديك من البلاستيك المناسب للاستخدام ويوفر عمراً طويلاً.\r\n\r\nيسمح التصميم الخاص المخفي بين ألواح الديك بالحصول على سطح جمالي. يقلل التركيب السهل من وقت العمالة.\r\n\r\nيمكن استخدامه بأمان في التطبيقات الداخلية والخارجية.','المادة: بلاستيك\r\nالحجم: راجع الصورة.\r\nسمك الديك المتوافق: 18-25 ملم\r\nالتعبئة: 1000 قطعة/صندوق','نظام تثبيت خفي\r\nهيكل بلاستيكي\r\nتركيب سهل\r\nمتوافق مع أنواع الديك القياسية','','','كليب الديك، كليب الديك البلاستيكي',NULL,NULL,NULL,NULL,NULL,'',''),(27,1,'tr','Metal Deck Klips Pro 316','Paslanmaz 316 çelikten üretilen, deniz ortamına dayanıklı profesyonel deck klips sistemi.','Metal Deck Klips Pro 316, özellikle kıyı şeridi ve denize yakın alanlarda kullanım için tasarlanmış, AISI 316 paslanmaz çelik alaşımından üretilmiş premium deck montaj klips sistemidir.\r\n\r\nYüksek tuz ve nem direnci sayesinde yıllarca bakım gerektirmez. Görünmez montaj sistemiyle estetik yüzey sağlar.\r\n\r\nProfesyonel projelerde güvenle tercih edilen, 10 yıl garantili ürünümüz ile deck sisteminiz dayanıklılık ve şıklığı bir arada sunar.','Malzeme: AISI 316 Paslanmaz Çelik\r\nBoyut: 52mm x 28mm x 3mm\r\nKaplama: Elektrolitik Parlatma\r\nDayanım: -40°C ile +200°C arası\r\nISO Sertifika: 9001:2015\r\nPaket: 100 adet/kutu','Korozyona karşı maksimum direnç\r\nDeniz ortamı sertifikası\r\nGörünmez montaj sistemi\r\n10 yıl ürün garantisi\r\nKolaylaştırılmış kurulum\r\nTüm deck panellerine uyumlu','','','',NULL,NULL,NULL,NULL,NULL,'',''),(28,1,'en','Metal Deck Clips Pro 316','Professional deck clip system made of stainless steel 316, resistant to marine environments.','Metal Deck Clips Pro 316 is a premium deck mounting clip system made from AISI 316 stainless steel alloy, specifically designed for use in coastal and near-sea areas.<br><br>\r\n\r\nThanks to its high resistance to salt and moisture, it requires no maintenance for years. The invisible mounting system ensures an aesthetic surface.<br><br>\r\n\r\nOur 10-year guaranteed product, preferred with confidence in professional projects, combines durability and elegance for your deck system.','Material: AISI 316 Stainless Steel<br>Size: 52mm x 28mm x 3mm<br>Coating: Electrolytic Polishing<br>Resistance: Between -40°C and +200°C<br>ISO Certification: 9001:2015<br>Package: 100 units/box','Maximum resistance to corrosion<br>Marine environment certification<br>Invisible mounting system<br>10-year product warranty<br>Simplified installation<br>Compatible with all deck panels','','','metal, deck, clips, pro, 316, deck klips',NULL,NULL,NULL,NULL,NULL,'',''),(29,1,'ar','مشبك ديك برو 316 المعدني','نظام مشابك احترافي للديك مصنوع من الفولاذ المقاوم للصدأ 316، مقاوم لبيئات البحر.','مشبك ديك برو 316 المعدني هو نظام مشابك تركيب للديك مصنوع من سبائك الفولاذ المقاوم للصدأ AISI 316، مصمم خصيصاً للاستخدام في المناطق الساحلية والقريبة من البحر.\r\n\r\nبفضل مقاومته العالية للملوحة والرطوبة، لا يتطلب صيانة لسنوات عديدة. يوفر نظام التركيب غير المرئي سطحاً جمالياً.\r\n\r\nيُفضل بثقة في المشاريع الاحترافية، منتجنا المضمون لمدة 10 سنوات يجمع بين المتانة والأناقة لنظام الديك الخاص بك.','المادة: الفولاذ المقاوم للصدأ AISI 316\r\nالأبعاد: 52مم × 28مم × 3مم\r\nالطلاء: تلميع إلكتروليتي\r\nالمقاومة: بين -40°م و +200°م\r\nشهادة ISO: 9001:2015\r\nالتعبئة: 100 قطعة/صندوق','أقصى مقاومة للتآكل\r\nشهادة بيئات البحر\r\nنظام تركيب غير مرئي\r\nضمان المنتج لمدة 10 سنوات\r\nتركيب سهل وميسر\r\nمتوافق مع جميع ألواح الديك','','','مشبك, ديك, برو, 316, المعدني, deck klips',NULL,NULL,NULL,NULL,NULL,'',''),(30,5,'tr','Yan Gizli Bağlantı Deck Klipsi','Deck panellerinin yan kenarlarından gizli bağlantı sağlayan profesyonel metal klips.','Yan Gizli Bağlantı Deck Klipsi, deck panellerinin yan kenarlarından birbirine bağlanmasını sağlayan özel tasarımlı bir metal klips sistemidir.\r\n\r\nPaneller arasında eşit boşluk bırakarak doğal ahşap genleşmesine olanak tanır. Bu sayede deck yüzeyinde çatlama ve eğilme önlenir.\r\n\r\nPaslanmaz çelik gövdesi ve ergonomik tasarımı ile hızlı ve güvenli montaj imkanı sunar. Teras, havuz kenarı ve balkon uygulamalarında idealdir.','Malzeme: Sac  + Kaplama\r\nBoyut: STANDART\r\nPaket: 1000 adet/kutu\r\n','Yan gizli bağlantı\r\nDoğal genleşme payı\r\nEşit panel aralığı\r\nHızlı montaj\r\nDış mekan uyumlu','','','DECK Klips, T DECK Klips, 8mm DECK Klips',NULL,NULL,NULL,NULL,NULL,'',''),(31,5,'en','Side Hidden Connection Deck Clip','Professional metal clip providing hidden connection from the side edges of deck panels.','The Side Hidden Connection Deck Clip is a specially designed metal clip system that allows deck panels to be connected from their side edges.<br><br>It ensures equal spacing between panels, accommodating natural wood expansion. This prevents cracking and warping on the deck surface.<br><br>With its stainless steel body and ergonomic design, it offers fast and secure installation. Ideal for terraces, poolside areas, and balcony applications.','Material: Sheet Metal + Coating<br>Size: STANDARD<br>Package: 1000 units/box','Side hidden connection<br>Natural expansion allowance<br>Equal panel spacing<br>Fast installation<br>Outdoor compatible','','','DECK Clip, T DECK Clip, 8mm DECK Clip',NULL,NULL,NULL,NULL,NULL,'',''),(32,5,'ar','كليب أرضية مخفي الجانب','كليب معدني احترافي يوفر توصيلاً مخفياً من الحواف الجانبية لألواح الأرضية.','كليب أرضية مخفي الجانب هو نظام كليب معدني مصمم خصيصاً لتوصيل ألواح الأرضية من الحواف الجانبية ببعضها البعض.\r\n\r\nيسمح بوجود مسافة متساوية بين الألواح لتمكين التمدد الطبيعي للخشب، مما يمنع حدوث التشققات والانحناءات على سطح الأرضية.\r\n\r\nيتميز بجسمه المصنوع من الفولاذ المقاوم للصدأ وتصميمه Ergonomي الذي يوفر تركيباً سريعاً وآمناً. مثالي للتطبيقات في الشرفات، جوانب حمامات السباحة والشرفات الصغيرة.','المادة: صفيحة + طلاء\r\nالحجم: قياسي\r\nالتعبئة: 1000 قطعة/صندوق','توصيل مخفي من الجانب\r\nمسافة تمدد طبيعية\r\nمسافة متساوية بين الألواح\r\nتركيب سريع\r\nمناسب للاستخدام الخارجي','','','كليب أرضية DECK، كليب أرضية T، كليب أرضية 8 ملم',NULL,NULL,NULL,NULL,NULL,'',''),(33,10,'tr','Gizli Montaj Plastik Deck Aparatı','Vida ve bağlantı noktalarını gizleyen estetik plastik deck montaj aparatı.','Gizli Montaj Plastik Deck Aparatı, deck yüzeyinde hiçbir bağlantı elemanının görünmemesini sağlayan özel tasarımlı bir plastik klips sistemidir.\r\n\r\nDeck panellerinin altına monte edilen aparat, tüm bağlantı noktalarını gizler. Bu sayede pürüzsüz ve estetik bir deck yüzeyi elde edilir.\r\n\r\nYüksek yoğunluklu polimer yapısı ile dayanıklıdır. UV dayanımı sayesinde dış mekan uygulamalarında güvenle kullanılabilir. Özellikle lüks villa ve otel projelerinde tercih edilir.','Malzeme: Yüksek Yoğunluklu Poliamid (PA66)\r\nBoyut: 42mm x 20mm x 6mm\r\nMontaj Tipi: Gizli\r\nRenk: Siyah / Kahverengi / Gri\r\nPaket: 300 adet/kutu\r\nGaranti: 7 Yıl','Tam gizli montaj\r\nEstetik yüzey\r\nUV dayanımlı\r\nKolay hizalama\r\nLüks proje uyumlu','','','',NULL,NULL,NULL,NULL,NULL,'',''),(34,10,'en','Hidden Mount Plastic Deck Clip','Aesthetic plastic deck mounting clip that conceals screws and connection points.','The Hidden Mount Plastic Deck Clip is a specially designed plastic clip system that ensures no fasteners are visible on the deck surface.\r\n\r\nMounted beneath the deck panels, the clip conceals all connection points, resulting in a smooth and aesthetic deck surface.\r\n\r\nConstructed from high-density polymer, it is highly durable. Thanks to its UV resistance, it can be safely used in outdoor applications. It is particularly preferred in luxury villa and hotel projects.','Material: High-Density Polyamide (PA66)\r\nSize: 42mm x 20mm x 6mm\r\nMounting Type: Hidden\r\nColor: Black / Brown / Gray\r\nPackage: 300 units/box\r\nWarranty: 7 Years','Fully hidden mounting\r\nAesthetic surface\r\nUV resistant\r\nEasy alignment\r\nCompatible with luxury projects','','','hidden, mount, plastic, deck, clip, deck klips',NULL,NULL,NULL,NULL,NULL,'',''),(35,10,'ar','مشبك أرضية بلاستيكي للتركيب الخفي','مشبك بلاستيكي لتركيب أرضيات الخشب يخفي البراغي ونقاط التوصيل بشكل جمالي.','مشبك أرضية بلاستيكي للتركيب الخفي هو نظام مشابك بلاستيكية مصمم خصيصاً لضمان عدم ظهور أي عناصر توصيل على سطح الأرضية الخشبية.\r\n\r\nيتم تركيب المشبك تحت ألواح الأرضية، مما يخفي جميع نقاط التوصيل. وبهذه الطريقة، يتم الحصول على سطح أرضية أملس وجمالي.\r\n\r\nيتميز ببنيته البوليمرية عالية الكثافة والمتينة. وبفضل مقاومته للأشعة فوق البنفسجية، يمكن استخدامه بأمان في التطبيقات الخارجية. يُفضل بشكل خاص في مشاريع الفلل الفاخرة والفنادق.','المادة: بولي أميد عالي الكثافة (PA66)\r\nالأبعاد: 42 ملم × 20 ملم × 6 ملم\r\nنوع التركيب: خفي\r\nاللون: أسود / بني / رمادي\r\nالتعبئة: 300 قطعة/صندوق\r\nالضمان: 7 سنوات','تركيب خفي تماماً\r\nسطح جمالي\r\nمقاوم للأشعة فوق البنفسجية\r\nسهولة المحاذاة\r\nمناسب للمشاريع الفاخرة','','','مشبك, أرضية, بلاستيكي, للتركيب, الخفي, deck klips',NULL,NULL,NULL,NULL,NULL,'',''),(36,2,'tr','Plastik Deck Klips UV-Pro','UV dayanımlı yüksek yoğunluklu polimer yapısıyla üstün performans sunan deck klips sistemi.','Plastik Deck Klips UV-Pro, güneş ışınlarına karşı maksimum dayanıklılık için özel UV stabilizatör katkı maddesiyle üretilen, yüksek yoğunluklu polimer bazlı bir deck montaj sistemidir.\r\n\r\nTüm dış mekan uygulamaları için idealdir. Çevre dostu malzemeden üretilmiş olup, geri dönüşüme uygundur.\r\n\r\n15 yıl renk stabilitesi garantisi ile uzun ömürlü kullanım sağlar.','Malzeme: UV Stabilize HDPE Polimer\r\nBoyut: STANDART\r\nRenk: Kahverengi\r\nPaket: 1000 adet/kutu','UV-A ve UV-B ışınlarına tam direnç\r\nÇevre dostu malzeme\r\nKolay kurulum\r\nDarbe ve çizilme direnci\r\nHafif ve ekonomik','','','DECK Klips, Plastik Deck Klips UV-Pro, Plastik Deck Klips, Deck Klips Plastik',NULL,NULL,NULL,NULL,NULL,'',''),(37,2,'en','Plastic Deck Clip UV-Pro','Deck clip system offering superior performance with UV-resistant high-density polymer structure.','Plastic Deck Clip UV-Pro is a high-density polymer-based deck mounting system manufactured with a special UV stabilizer additive for maximum resistance against sunlight.<br><br>Ideal for all outdoor applications. Produced from eco-friendly materials and suitable for recycling.<br><br>Provides long-lasting use with a 15-year color stability guarantee.','Material: UV-Stabilized HDPE Polymer<br>Size: STANDARD<br>Color: Brown<br>Package: 1000 units/box','Full resistance to UV-A and UV-B rays<br>Eco-friendly material<br>Easy installation<br>Impact and scratch resistance<br>Lightweight and economical','','','DECK Clip, Plastic Deck Clip UV-Pro, Plastic Deck Clip, Deck Clip Plastic',NULL,NULL,NULL,NULL,NULL,'',''),(38,2,'ar','كليب أرضية بلاستيكي مقاوم للأشعة فوق البنفسجية UV-Pro','نظام كليب أرضية مصنوع من بوليمر عالي الكثافة مقاوم للأشعة فوق البنفسجية يوفر أداءً فائقًا.','كليب أرضية بلاستيكي UV-Pro هو نظام تركيب أرضيات مصنوع من بوليمر عالي الكثافة مضاف إليه مثبتات خاصة للأشعة فوق البنفسجية لضمان أقصى مقاومة لأشعة الشمس.\r\n\r\nمثالي لجميع التطبيقات الخارجية. مصنوع من مواد صديقة للبيئة وقابل لإعادة التدوير.\r\n\r\nيوفر ضمان ثبات اللون لمدة 15 عامًا للاستخدام طويل الأمد.','المادة: بوليمر HDPE المثبت بالأشعة فوق البنفسجية\r\nالحجم: قياسي\r\nاللون: بني\r\nالتعبئة: 1000 قطعة/صندوق','مقاومة كاملة لأشعة UV-A وUV-B\r\nمادة صديقة للبيئة\r\nسهولة التركيب\r\nمقاومة للصدمات والخدوش\r\nخفيف واقتصادي','','','كليب أرضية DECK، كليب أرضية بلاستيكي مقاوم للأشعة فوق البنفسجية UV-Pro، كليب أرضية بلاستيكي، كليب أرضية بلاستيك',NULL,NULL,NULL,NULL,NULL,'',''),(39,6,'tr','Profesyonel Deck Montaj Klipsi','Profesyonel uygulamalar için tasarlanmış, yüksek dayanımlı metal deck montaj klipsi.','Profesyonel Deck Montaj Klipsi, büyük ölçekli deck projeleri ve profesyonel montaj ekipleri için geliştirilmiş üstün performanslı bir üründür.\r\n\r\nÇift kilit mekanizması ile deck panelini alt yapıya sıkıca sabitler. Titreşim ve darbe dayanımı yüksektir.\r\n\r\nÖzel yüzey işlemi sayesinde çizilme ve aşınmaya karşı dirençlidir. Tüm metal ve ahşap alt yapılarla uyumludur.\r\n\r\nTicari projeler, restoran terasları ve otel havuz alanları için ideal bir çözümdür.','Malzeme: Sertleştirilmiş Sac + Kaplama\r\nBoyut: 4,5Cm x 4,5Cm x 1,5Cm\r\nKilit Mekanizması: Çift Kilit\r\nPaket: 1000 adet/kutu\r\n','Çift kilit mekanizması\r\nYüksek darbe dayanımı\r\nÇizilme direnci\r\nTicari kullanım uyumlu\r\nProfesyonel montaj','','','',NULL,NULL,NULL,NULL,NULL,'',''),(40,6,'en','Professional Deck Mounting Clip','High-strength metal deck mounting clip designed for professional applications.','The Professional Deck Mounting Clip is a high-performance product developed for large-scale deck projects and professional installation teams.<br><br>It securely fastens the deck panel to the substructure with a dual-lock mechanism. It offers high resistance to vibration and impact.<br><br>The special surface treatment ensures resistance to scratches and wear. Compatible with all metal and wooden substructures.<br><br>An ideal solution for commercial projects, restaurant terraces, and hotel pool areas.','Material: Hardened Steel + Coating<br>Dimensions: 4.5 cm x 4.5 cm x 1.5 cm<br>Lock Mechanism: Dual Lock<br>Package: 1000 units/box','Dual-lock mechanism<br>High impact resistance<br>Scratch resistance<br>Suitable for commercial use<br>Professional installation','','','professional, deck, mounting, clip, deck klips',NULL,NULL,NULL,NULL,NULL,'',''),(41,6,'ar','مشبك تركيب أرضيات احترافي','مشبك تركيب أرضيات معدني عالي المتانة مصمم للتطبيقات الاحترافية.','مشبك تركيب الأرضيات الاحترافي هو منتج عالي الأداء تم تطويره لمشاريع الأرضيات واسعة النطاق وفرق التركيب المحترفة.\r\n\r\nيقوم بتثبيت لوحة الأرضية بإحكام على البنية التحتية بفضل آلية القفل المزدوج. يتمتع بمقاومة عالية للاهتزازات والصدمات.\r\n\r\nيعمل المعالجة السطحية الخاصة به على مقاومة الخدوش والتآكل، وهو متوافق مع جميع الهياكل المعدنية والخشبية.\r\n\r\nيُعد الحل المثالي للمشاريع التجارية، وأرضيات المطاعم، ومناطق حمامات الفنادق.','المادة: صفيحة مقساة + طلاء\r\nالأبعاد: 4.5 سم × 4.5 سم × 1.5 سم\r\nآلية القفل: قفل مزدوج\r\nالتعبئة: 1000 قطعة/صندوق','آلية قفل مزدوج\r\nمقاومة عالية للصدمات\r\nمقاومة الخدش\r\nمناسب للاستخدام التجاري\r\nتركيب احترافي','','','مشبك, تركيب, أرضيات, احترافي, deck klips',NULL,NULL,NULL,NULL,NULL,'',''),(42,11,'tr','Darbe Dayanımlı Plastik Deck Klipsi','Yüksek darbe direncine sahip, takviyeli polimer yapılı dayanıklı plastik deck klipsi.','Darbe Dayanımlı Plastik Deck Klipsi, cam elyaf takviyeli polimer yapısıyla standart plastik klipslere göre 3 kat daha fazla darbe dayanımı sunar.\r\n\r\nAğır yük ve sık kullanım gerektiren alanlar için tasarlanmıştır. Ticari deck uygulamaları, restoran terasları ve kamusal alanlar için idealdir.\r\n\r\nKorozyon yapmaz, paslanmaz ve kimyasal maddelere karşı dirençlidir. Düşük sıcaklıklarda bile esnekliğini korur.','Malzeme: Cam Elyaf Takviyeli Polimer\r\nBoyut: 50mm x 26mm x 5mm\r\nDarbe Direnci: 3x standart\r\nÇalışma Sıcaklığı: -40°C ile +90°C\r\nPaket: 150 adet/kutu\r\nGaranti: 12 Yıl','3x darbe dayanımı\r\nCam elyaf takviye\r\nKimyasal direnç\r\nDüşük sıcaklık esnekliği\r\nTicari kullanım','','','',NULL,NULL,NULL,NULL,NULL,'',''),(43,11,'en','Impact-Resistant Plastic Deck Clip','Durable plastic deck clip with high impact resistance, reinforced polymer structure.','The Impact-Resistant Plastic Deck Clip offers 3 times greater impact resistance compared to standard plastic clips, thanks to its fiberglass-reinforced polymer structure.<br><br>Designed for areas requiring heavy loads and frequent use, it is ideal for commercial deck applications, restaurant terraces, and public spaces.<br><br>It is corrosion-resistant, rust-proof, and resistant to chemicals. It maintains flexibility even at low temperatures.','Material: Fiberglass-Reinforced Polymer<br>Size: 50mm x 26mm x 5mm<br>Impact Resistance: 3x standard<br>Operating Temperature: -40°C to +90°C<br>Package: 150 units/box<br>Warranty: 12 Years','3x impact resistance<br>Fiberglass reinforcement<br>Chemical resistance<br>Low-temperature flexibility<br>Commercial use','','','impact-resistant, plastic, deck, clip, deck klips',NULL,NULL,NULL,NULL,NULL,'',''),(44,11,'ar','كليپس أرضية بلاستيكي مقاوم للصدمات','كليپس أرضية بلاستيكي متين مصنوع من البوليمر المقوى بمقاومة عالية للصدمات.','يوفر كليپس الأرضية البلاستيكي المقاوم للصدمات، المصنوع من البوليمر المقوى بألياف الزجاج، مقاومة للصدمات تفوق بمقدار 3 أضعاف مقاومتها في الكليپس البلاستيكية القياسية.\r\n\r\nتم تصميمه للمناطق التي تتطلب تحمل الأحمال الثقيلة والاستخدام المتكرر. مثالي لتطبيقات الأرضيات التجارية، وتراسات المطاعم، والمساحات العامة.\r\n\r\nلا يصدأ، مقاوم للتآكل، ومقاوم للمواد الكيميائية. يحافظ على مرونته حتى في درجات الحرارة المنخفضة.','المادة: بوليمر مقوى بألياف الزجاج\r\nالأبعاد: 50 ملم × 26 ملم × 5 ملم\r\nمقاومة الصدمات: 3 أضعاف المعيار\r\nدرجة حرارة التشغيل: من -40 درجة مئوية إلى +90 درجة مئوية\r\nالتعبئة: 150 قطعة/صندوق\r\nالضمان: 12 سنة','مقاومة صدمات بمقدار 3 أضعاف\r\nتعزيز بألياف الزجاج\r\nمقاومة كيميائية\r\nمرونة في درجات الحرارة المنخفضة\r\nاستخدام تجاري','','','كليپس, أرضية, بلاستيكي, مقاوم, للصدمات, deck klips',NULL,NULL,NULL,NULL,NULL,'',''),(47,4,'tr','Paslanmaz Çelik Deck Sabitleme Klipsi','Yüksek korozyon direncine sahip, ağır yük kapasiteli paslanmaz çelik deck sabitleme klipsi.','Paslanmaz Çelik Deck Sabitleme Klipsi, yüksek korozyon direnci ve ağır yük taşıma kapasitesi ile endüstriyel ve ticari deck projeleri için idealdir.\r\n\r\nAISI 316 paslanmaz çelik alaşımından üretilen bu klips, deniz ortamları ve yüksek nemli bölgelerde bile paslanma yapmaz.\r\n\r\nÖzel diş yapısı sayesinde deck panelini sabitlerken kayma ve gevşeme yapmaz. Profesyonel montaj ekiplerinin tercih ettiği güvenilir bir çözümdür.','Malzeme: AISI 316 Paslanmaz Çelik\r\nBoyut: 40mm x 40mm x 1.5mm\r\nPaket: 1000 adet/kutu','AISI 316 paslanmaz çelik\r\nYüksek taşıma kapasitesi\r\nDeniz ortamı uyumlu\r\nKayma ve gevşeme yapmaz.','','','Paslanmaz Çelik Deck Klips, Deck Klips, Paslanmaz Deck Klips',NULL,NULL,NULL,NULL,NULL,'',''),(48,4,'en','Stainless Steel Deck Fixing Clip','High corrosion-resistant stainless steel deck fixing clip with heavy load capacity.','The Stainless Steel Deck Fixing Clip is ideal for industrial and commercial deck projects, offering high corrosion resistance and heavy load-bearing capacity.\r\n\r\nManufactured from AISI 316 stainless steel alloy, this clip does not rust even in marine environments and high-humidity areas.\r\n\r\nThanks to its special thread design, it prevents slipping and loosening while securing the deck panel. It is a reliable solution preferred by professional installation teams.','Material: AISI 316 Stainless Steel<br>Size: 40mm x 40mm x 1.5mm<br>Package: 1000 units/box','AISI 316 stainless steel<br>High load-bearing capacity<br>Compatible with marine environments<br>Resistant to slipping and loosening.','','','Stainless Steel Deck Clip, Deck Clip, Stainless Deck Clip',NULL,NULL,NULL,NULL,NULL,'',''),(49,4,'ar','مشبك تثبيت أرضية من الفولاذ المقاوم للصدأ','مشبك تثبيت أرضية من الفولاذ المقاوم للصدأ ذو مقاومة عالية للتآكل وسعة تحميل عالية للأحمال الثقيلة.','مشبك تثبيت أرضية من الفولاذ المقاوم للصدأ مثالي للمشاريع الصناعية والتجارية بفضل مقاومته العالية للتآكل وسعة تحميل الأحمال الثقيلة.\r\n\r\nيُصنع هذا المشبك من سبيكة الفولاذ المقاوم للصدأ AISI 316، مما يضمن عدم تعرضه للصدأ حتى في البيئات البحرية والمناطق ذات الرطوبة العالية.\r\n\r\nبفضل هيكل الأسنان الخاص به، يقوم بتثبيت لوح الأرضية دون انزلاق أو ارتخاء، وهو حل موثوق به يُفضله فرق التركيب المحترفة.','المادة: الفولاذ المقاوم للصدأ AISI 316\r\nالأبعاد: 40 ملم × 40 ملم × 1.5 ملم\r\nالتعبئة: 1000 قطعة/صندوق','الفولاذ المقاوم للصدأ AISI 316\r\nسعة تحميل عالية\r\nمناسب للبيئات البحرية\r\nلا ينزلق أو يرتخي.','','','مشبك أرضية من الفولاذ المقاوم للصدأ، مشبك أرضية، مشبك أرضية مقاوم للصدأ',NULL,NULL,NULL,NULL,NULL,'',''),(50,12,'tr','Ekonomik Plastik Deck Bağlantı Klipsi','Bütçe dostu, güvenilir performans sunan standart plastik deck bağlantı klipsi.','Ekonomik Plastik Deck Bağlantı Klipsi, uygun fiyatı ve güvenilir performansı ile bütçe odaklı deck projeleri için tasarlanmıştır.\r\n\r\nStandart dış mekan koşullarında sorunsuz çalışan bu klips, ev bahçeleri, küçük teraslar ve DIY projeleri için idealdir.\r\n\r\nHafif yapısı sayesinde kolay taşınır ve monte edilir. Standart deck panelleriyle tam uyumludur. Toplu alımlarda ekstra indirim imkanı mevcuttur.','Malzeme: Polipropilen (PP)\r\nBoyut: 40mm x 20mm x 3mm\r\nUyumlu Deck: Standart 18-22mm\r\nRenk: Siyah\r\nPaket: 500 adet/kutu\r\nGaranti: 5 Yıl','Ekonomik fiyat\r\nKolay montaj\r\nHafif\r\nToplu alım avantajı\r\nDIY proje uyumlu','','','',NULL,NULL,NULL,NULL,NULL,'',''),(51,12,'en','Economical Plastic Deck Clip','Budget-friendly standard plastic deck clip offering reliable performance.','The Economical Plastic Deck Clip is designed for budget-focused deck projects, combining affordability with dependable performance.<br><br>This clip operates seamlessly under standard outdoor conditions, making it ideal for home gardens, small terraces, and DIY projects.<br><br>Its lightweight construction ensures easy handling and installation, and it is fully compatible with standard deck panels. Additional discounts are available for bulk purchases.','Material: Polypropylene (PP)<br>Dimensions: 40mm x 20mm x 3mm<br>Compatible Deck: Standard 18-22mm<br>Color: Black<br>Packaging: 500 units/box<br>Warranty: 5 Years','Cost-effective<br>Easy installation<br>Lightweight<br>Bulk purchase advantages<br>DIY project compatible','','','economical, plastic, deck, clip, deck klips',NULL,NULL,NULL,NULL,NULL,'',''),(52,12,'ar','كليب ربط أرضية بلاستيكي اقتصادي','كليب ربط أرضية بلاستيكي قياسي يقدم أداءً موثوقاً وبسعر مناسب للميزانية.','كليب ربط أرضية بلاستيكي اقتصادي مصمم لمشاريع الأرضيات التي تركز على الميزانية، حيث يجمع بين السعر المناسب والأداء الموثوق.\r\n\r\nيعمل هذا الكليب بسلاسة في ظروف الطقس الخارجية القياسية، مما يجعله مثالياً لحدائق المنازل، والشرفات الصغيرة، ومشاريع DIY.\r\n\r\nبفضل هيكله الخفيف، يسهل نقله وتركيبه، كما أنه متوافق تماماً مع ألواح الأرضيات القياسية. تتوفر خصومات إضافية عند الشراء بكميات كبيرة.','المادة: بولي بروبيلين (PP)\r\nالحجم: 40 ملم × 20 ملم × 3 ملم\r\nالتوافق مع الأرضيات: قياسي 18-22 ملم\r\nاللون: أسود\r\nالتعبئة: 500 قطعة/صندوق\r\nالضمان: 5 سنوات','سعر اقتصادي\r\nسهولة التركيب\r\nخفيف الوزن\r\nمزايا الشراء بكميات كبيرة\r\nمتوافق مع مشاريع DIY','','','كليب, ربط, أرضية, بلاستيكي, اقتصادي, deck klips',NULL,NULL,NULL,NULL,NULL,'',''),(53,7,'tr','Yüksek Dayanımlı Deck Bağlantı Klipsi','Ekstra kalın yapısıyla yüksek yük taşıma kapasitesine sahip dayanıklı deck bağlantı klipsi.','Yüksek Dayanımlı Deck Bağlantı Klipsi, ekstra kalın metal yapısı ve güçlendirilmiş tasarımı ile ağır yük taşıma gerektiren deck projeleri için üretilmiştir.\r\n\r\n3mm kalınlığındaki gövdesi sayesinde standart klipslere göre %40 daha fazla yük taşır. Endüstriyel alanlar, araç geçişli deck platformları ve ticari kullanım için uygundur.\r\n\r\nPaslanmaz çelik bağlantı noktaları ve korozyon önleyici kaplama ile uzun ömürlü kullanım sağlar. Zorlu hava koşullarına karşı test edilmiştir.','Malzeme: Sertleştirilmiş Sac\r\nBoyut: 4,5cm x 4,5cm x 2mm\r\nPaket: 500 adet/kutu\r\n','Ekstra kalın 2mm sac\r\n%40 daha yüksek yük kapasitesi\r\nZorlu hava koşullarına dayanıklı\r\nEndüstriyel kullanım','','','Yüksek Dayanımlı Deck Bağlantı Klipsi, Deck Bağlantı Klipsi, Deck Klipsi, Kalın Deck Klipsi',NULL,NULL,NULL,NULL,NULL,'',''),(54,7,'en','High-Strength Deck Connection Clip','Durable deck connection clip with extra-thick structure for high load-bearing capacity.','The High-Strength Deck Connection Clip is manufactured with an extra-thick metal structure and reinforced design for deck projects requiring heavy load-bearing capacity.\r\n\r\nWith its 3mm thick body, it carries 40% more load compared to standard clips. Suitable for industrial areas, vehicle-accessible deck platforms, and commercial use.\r\n\r\nFeaturing stainless steel connection points and anti-corrosive coating, it ensures long-lasting performance. Tested against harsh weather conditions.','Material: Hardened Sheet Metal<br>Size: 4.5cm x 4.5cm x 2mm<br>Package: 500 units/box','Extra-thick 2mm sheet metal<br>40% higher load capacity<br>Resistant to harsh weather conditions<br>Industrial use','','','High-Strength Deck Connection Clip, Deck Connection Clip, Deck Clip, Thick Deck Clip',NULL,NULL,NULL,NULL,NULL,'',''),(55,7,'ar','كليب ربط أرضيات عالي المتانة','كليب ربط أرضيات متين بسماكة إضافية وقدرة تحمل عالية للأحمال.','كليب ربط أرضيات عالي المتانة مصمم بمعدن سميك للغاية وتصميم مقوى لمشاريع الأرضيات التي تتطلب تحمل أحمال ثقيلة.\r\n\r\nبفضل هيكله بسمك 3 ملم، يحمل هذا الكليب حمولة تزيد بنسبة 40% عن الكليبات القياسية. مناسب للمناطق الصناعية ومنصات الأرضيات المخصصة لمرور المركبات والاستخدام التجاري.\r\n\r\nيوفر نقاط ربط من الفولاذ المقاوم للصدأ وطلاء مقاوم للتآكل لضمان استخدام طويل الأمد. تم اختباره لمقاومة الظروف الجوية القاسية.','المادة: صفيحة صلبة\r\nالأبعاد: 4.5 سم × 4.5 سم × 2 ملم\r\nالتعبئة: 500 قطعة/صندوق','صفيحة سميكة بسمك 2 ملم إضافي\r\nقدرة تحمل أعلى بنسبة 40%\r\nمقاوم للظروف الجوية القاسية\r\nللاستخدام الصناعي','','','كليب ربط أرضيات عالي المتانة, كليب ربط أرضيات, كليب أرضيات, كليب أرضيات سميك',NULL,NULL,NULL,NULL,NULL,'',''),(62,13,'tr','T Deck Klipsi','Yüksek kaliteli T Deck Klipsi ile ahşap veya kompozit deck döşemelerinizi güvenle sabitleyin. Uzun ömürlü ve dayanıklı performans sunar.','T Deck Klipsi, deck döşeme projelerinizde profesyonel ve estetik bir montaj çözümü arayanlar için ideal bir üründür. Ahşap, kompozit veya WPC deck malzemelerinin gizli ve güvenli bir şekilde sabitlenmesini sağlayan bu klipsler, döşemeler arasında eşit aralıklar bırakarak hem görsel hem de yapısal bütünlük sunar.\r\n\r\nT Deck Klipsi, korozyona ve dış etkenlere karşı üstün direnç gösterir. Kolay ve hızlı montaj imkanı sunan klipsler, vida delikleri sayesinde zemine sağlam bir şekilde tutturulur ve döşeme tahtalarının hareket etmesini engeller.\r\n\r\nT Deck Klipsi, özellikle geniş alanlarda ve yoğun kullanıma maruz kalan decklerde tercih edilen bir üründür. Hem konut hem de ticari projelerde güvenle kullanılabilir. Deck döşemelerinizin ömrünü uzatırken, bakım gereksinimini de minimuma indirir. Estetik görünümü ve dayanıklılığı ile deck projelerinizin montajını bir üst seviyeye taşıyın.','Malzeme: Sertleştirilmiş Sac + Kaplama\r\nBoyut: 4,5Cm x 4,5Cm x 1,5Cm\r\nKilit Mekanizması: Çift Kilit\r\nPaket: 1000 adet/kutu\r\n','Korozyona karşı dayanıklılık,Gizli montaj sistemi ile estetik ve düzgün görünüm,Döşeme tahtaları arasında eşit aralıklar sağlar,Kolay ve hızlı montaj imkanı,Uzun ömürlü ve bakım gerektirmeyen yapı,Ahşap ve kompozit deck malzemeleri ile uyumlu,Yüksek yük taşıma kapasitesi,Dış mekan koşullarına karşı dirençli,Hem konut hem de ticari projelerde kullanılabilir,Vida delikleri sayesinde sağlam sabitleme','','','T deck klipsi, deck montaj klipsi, paslanmaz çelik deck klipsi, gizli deck klipsi, kompozit deck klipsi, ahşap deck klipsi, deck döşeme klipsi, teras montaj klipsi, WPC deck klipsi, dış mekan deck klipsi, dayanıklı deck klipsi, uzun ömürlü deck klipsi, deck sabitleme klipsi, profesyonel deck montajı',NULL,NULL,NULL,NULL,NULL,'',''),(63,13,'en','T Deck Clip','Securely fasten your wooden or composite deck boards with high-quality T Deck Clips. Offers long-lasting and durable performance.','The T Deck Clip is the ideal product for those seeking a professional and aesthetic mounting solution for their decking projects. These clips ensure hidden and secure fastening of wooden, composite, or WPC deck materials, providing both visual and structural integrity by maintaining even gaps between deck boards.\r\n\r\nT Deck Clips demonstrate superior resistance to corrosion and external factors. Offering easy and quick installation, the clips are firmly attached to the substructure through screw holes, preventing deck boards from shifting.\r\n\r\nT Deck Clips are particularly preferred for large areas and decks subject to heavy use. They can be safely used in both residential and commercial projects. Extend the lifespan of your deck boards while minimizing maintenance requirements. Elevate the installation of your deck projects with an aesthetic appearance and durability.','Material: Hardened Steel + Coating\r\nDimensions: 4.5 cm x 4.5 cm x 1.5 cm\r\nLocking Mechanism: Dual Lock\r\nPackage: 1000 units/box','Resistant to corrosion,<br>Aesthetic and neat appearance with hidden mounting system,<br>Ensures even gaps between deck boards,<br>Easy and quick installation,<br>Long-lasting and low-maintenance structure,<br>Compatible with wooden and composite deck materials,<br>High load-bearing capacity,<br>Resistant to outdoor conditions,<br>Suitable for both residential and commercial projects,<br>Secure fastening with screw holes','','','T deck clip, deck mounting clip, stainless steel deck clip, hidden deck clip, composite deck clip, wooden deck clip, deck board clip, terrace mounting clip, WPC deck clip, outdoor deck clip, durable deck clip, long-lasting deck clip, deck fastening clip, professional deck installation',NULL,NULL,NULL,NULL,NULL,'',''),(64,13,'ar','كليپس T ديك','ثبّت ألواح أرضيات الديك الخشبية أو المركبة بأمان باستخدام كليپس T ديك عالي الجودة. يوفر أداءً متيناً وطويل الأمد.','كليپس T ديك هو المنتج المثالي لمن يبحث عن حل تركيب احترافي وجمالي لمشاريع أرضيات الديك. تضمن هذه الكليپسات تثبيت الأخشاب أو المواد المركبة أو WPC بطريقة مخفية وآمنة، مما يوفر مسافات متساوية بين الألواح لتحقيق تكامل بصري وهيكلي.\r\n\r\nيتميز كليپس T ديك بمقاومته العالية للتآكل والعوامل الخارجية. توفر هذه الكليپسات تركيباً سهلاً وسريعاً بفضل ثقوب البراغي التي تضمن تثبيتها بقوة في الأرضية وتمنع حركة ألواح الديك.\r\n\r\nيُفضل استخدام كليپس T ديك خاصة في المساحات الواسعة والمناطق المعرضة للاستخدام الكثيف. يمكن استخدامه بأمان في المشاريع السكنية والتجارية على حد سواء. يطيل عمر أرضيات الديك ويقلل من متطلبات الصيانة إلى أدنى حد. ارفع مستوى تركيب مشاريع الديك الخاصة بك من خلال المظهر الجمالي والمتانة التي يوفرها كليپس T ديك.','المادة: صفيحة صلبة + طلاء\r\nالأبعاد: 4.5 سم × 4.5 سم × 1.5 سم\r\nآلية القفل: قفل مزدوج\r\nالتعبئة: 1000 قطعة/صندوق','مقاومة التآكل،<br>نظام تركيب مخفي يوفر مظهراً جمالياً ومنتظماً،<br>يوفر مسافات متساوية بين ألواح الديك،<br>سهولة وسرعة التركيب،<br>بنية طويلة الأمد ولا تتطلب صيانة،<br>متوافق مع الأخشاب والمواد المركبة لأرضيات الديك،<br>سعة تحميل عالية،<br>مقاوم لظروف الهواء الطلق،<br>يمكن استخدامه في المشاريع السكنية والتجارية،<br>تثبيت قوي بفضل ثقوب البراغي','','','كليپس T ديك، كليپس تركيب الديك، كليپس ديك من الفولاذ المقاوم للصدأ، كليپس ديك مخفي، كليپس ديك مركب، كليپس ديك خشبي، كليپس أرضيات الديك، كليپس تركيب الشرفات، كليپس ديك WPC، كليپس ديك خارجي، كليپس ديك متين، كليپس ديك طويل الأمد، كليپس تثبيت الديك، تركيب ديك احترافي',NULL,NULL,NULL,NULL,NULL,'',''),(80,9,'tr','Esnek Plastik Deck Sabitleme Klipsi','Esnek yapısıyla deck panellerinin genleşmesine uyum sağlayan plastik sabitleme klipsi.','Esnek Plastik Deck Sabitleme Klipsi, termoplastik elastomer yapısı sayesinde deck panellerinin sıcaklık değişimlerinde genleşip büzülmesine uyum sağlayan akıllı bir klips sistemidir.\r\n\r\nEsnek yapısı sayesinde panel üzerinde baskı yapmaz, çatlama ve kırılma riskini minimuma indirir. Özellikle büyük yüzey alanlı deck uygulamalarında tercih edilir.\r\n\r\nDarbe emici özelliği ile ayak konforunu artırır. Havuz kenarı, teras ve bahçe deck uygulamaları için idealdir.','Malzeme: Termoplastik Elastomer (TPE)\r\nBoyut: 45mm x 22mm x 5mm\r\nRenk: Siyah / Kahve\r\nPaket: 1000 adet/kutu','Termoplastik elastomer yapı\r\nGenleşme uyumu\r\nDarbe emici\r\nBüyük yüzey uyumlu\r\nKolay montaj','','','Plastik Deck Sabitleme Klipsi, Plastik Deck Klipsi, Deck Klipsi','[{\"q\":\"Esnek plastik deck klipsi ne işe yarar?\",\"a\":\"Deck kaplama tahtalarını gizli şekilde sabitleyerek vidaların görünmesini engeller ve estetik bir yüzey oluşturur.\"},{\"q\":\"Ürün dış mekân kullanımına uygun mu?\",\"a\":\"Evet, UV ışınlarına ve zorlu hava koşullarına dayanıklı esnek plastikten üretilmiştir. Uzun ömürlüdür.\"},{\"q\":\"Tüm deck sistemleriyle uyumlu mu?\",\"a\":\"Çoğu kompozit deck ve bazı ahşap deck sistemleriyle uyumludur. Uygulamadan önce ölçü ve kanal yapısının kontrol edilmesi önerilir.\"}]','[{\"name\":\"Hazırlık\",\"text\":\"Montaj öncesinde küçük bir alanda deneme yaparak klipsin deck tahtası ile uyumunu ve aralık mesafesini kontrol edin.\"},{\"name\":\"Klipslerin Yerleştirilmesi\",\"text\":\"Klipsleri alt taşıyıcı konstrüksiyona vidalayarak sabitleyin. Ardından deck tahtalarını klips aralarına dikkatlice yerleştirin.\"},{\"name\":\"Sabitleme ve Son Kontrol\",\"text\":\"Tüm vidaları sıkın, yüzey hizasını kontrol edin ve düzgün bir görünüm elde ettiğinizden emin olun.\"}]','esnek-plastik-deck-sabitleme-klipsi',NULL,NULL,'',''),(81,9,'en','Flexible Plastic Deck Fastening Clip','Plastic fastening clip that adapts to the expansion of deck panels with its flexible structure.','The Flexible Plastic Deck Fastening Clip is an intelligent clip system that accommodates the expansion and contraction of deck panels during temperature changes, thanks to its thermoplastic elastomer structure.<br><br>\r\n\r\nIts flexible design prevents pressure on the panel, minimizing the risk of cracking and breaking. It is particularly preferred for large-surface deck applications.<br><br>\r\n\r\nWith its shock-absorbing feature, it enhances foot comfort. Ideal for poolside, terrace, and garden deck applications.','Material: Thermoplastic Elastomer (TPE)\r\nSize: 45mm x 22mm x 5mm\r\nColor: Black / Brown\r\nPackaging: 1000 units/box','Thermoplastic elastomer structure\r\nExpansion compatibility\r\nShock-absorbing\r\nSuitable for large surfaces\r\nEasy installation','','','Plastic Deck Fastening Clip, Plastic Deck Clip, Deck Clip','[{\"q\":\"What is the purpose of the flexible plastic deck clip?\",\"a\":\"It secures decking boards in a concealed manner, preventing screws from being visible and creating an aesthetic surface.\"},{\"q\":\"Is the product suitable for outdoor use?\",\"a\":\"Yes, it is made from flexible plastic that is resistant to UV rays and harsh weather conditions, ensuring long-lasting durability.\"},{\"q\":\"Is it compatible with all decking systems?\",\"a\":\"It is compatible with most composite decking systems and some wooden deck systems. It is recommended to check the dimensions and channel structure before application.\"}]','[{\"name\":\"Preparation\",\"text\":\"Before installation, test the clip in a small area to verify compatibility with the deck board and check the spacing.\"},{\"name\":\"Placing the Clips\",\"text\":\"Secure the clips to the underlying support structure with screws. Then, carefully place the deck boards between the clips.\"},{\"name\":\"Fastening and Final Check\",\"text\":\"Tighten all screws, check the surface alignment, and ensure a smooth finish.\"}]','flexible-plastic-deck-fastening-clip',NULL,NULL,'',''),(82,9,'ar','كليب تثبيت أرضيات بلاستيكي مرن','كليب تثبيت بلاستيكي مرن يتكيف مع تمدد ألواح الأرضيات بفضل بنيته المرنة.','كليب تثبيت أرضيات بلاستيكي مرن هو نظام كليب ذكي مصنوع من مادة اللدائن الحرارية المرنة (TPE) والذي يتكيف مع تمدد وانكماش ألواح الأرضيات نتيجة لتغيرات درجات الحرارة.\r\n\r\nبفضل بنيته المرنة، لا يضغط على اللوح، مما يقلل من خطر التشقق والكسر إلى الحد الأدنى. يُفضل بشكل خاص في تطبيقات الأرضيات ذات المساحات الكبيرة.\r\n\r\nيتميز بخاصية امتصاص الصدمات مما يزيد من راحة المشي. مثالي لتطبيقات الأرضيات حول حمامات السباحة، والتراسات وحدائق المنازل.','المادة: لدائن حرارية مرنة (TPE)\r\nالأبعاد: 45 ملم × 22 ملم × 5 ملم\r\nاللون: أسود / بني\r\nالتعبئة: 1000 قطعة/صندوق','بنية لدائن حرارية مرنة\r\nالتكيف مع التمدد\r\nامتصاص الصدمات\r\nمناسب للمساحات الكبيرة\r\nسهولة التركيب','','','كليب تثبيت أرضيات بلاستيكي، كليب أرضيات بلاستيكي، كليب أرضيات','[{\"q\":\"ما فائدة كليب تثبيت الأرضيات البلاستيكي المرن؟\",\"a\":\"يقوم بتثبيت ألواح تغطية الأرضيات بشكل مخفي لمنع ظهور البراغي ويخلق سطحاً جمالياً.\"},{\"q\":\"هل المنتج مناسب للاستخدام في الأماكن الخارجية؟\",\"a\":\"نعم، مصنوع من بلاستيك مرن مقاوم للأشعة فوق البنفسجية وظروف الطقس القاسية، مما يضمن عمراً طويلاً.\"},{\"q\":\"هل يتوافق مع جميع أنظمة الأرضيات؟\",\"a\":\"يتوافق مع معظم أنظمة الأرضيات المركبة وبعض أنظمة الأرضيات الخشبية. يُنصح بالتحقق من القياسات وهيكل القناة قبل التطبيق.\"}]','[{\"name\":\"التحضير\",\"text\":\"قبل التركيب، قم بإجراء اختبار على مساحة صغيرة للتأكد من توافق الكليب مع لوح الأرضيات والتحقق من مسافة الفجوة.\"},{\"name\":\"وضع الكليب\",\"text\":\"قم بتثبيت الكليب على الهيكل الحامل السفلي باستخدام البراغي، ثم ضع ألواح الأرضيات بعناية بين الكليب.\"},{\"name\":\"التثبيت والفحص النهائي\",\"text\":\"قم بشد جميع البراغي، تحقق من مستوى السطح وتأكد من الحصول على مظهر متساوٍ.\"}]','',NULL,NULL,'',''),(83,8,'tr','UV Dayanımlı Plastik Deck Klipsi','Güneş ışınlarına karşı maksimum dayanıklılık sağlayan UV stabilize polimer deck klipsi.','UV Dayanımlı Plastik Deck Klipsi, özel UV stabilizatör katkı maddeleriyle üretilmiş, güneş ışınlarına karşı üstün direnç gösteren bir plastik deck klips sistemidir.\r\n\r\nYıllarca doğrudan güneş altında bile renk solması, kırılganlaşma veya deformasyon yapmaz. Tüm dış mekan deck uygulamaları için idealdir.\r\n\r\nHafif yapısı sayesinde kolay taşınır ve monte edilir. Çevre dostu malzemeden üretilmiş olup geri dönüşüme uygundur.','Malzeme: UV Stabilize HDPE Polimer\r\nBoyut: Standart\r\nUV Direnci: Max.\r\nRenk: Siyah / Kahverengi\r\nPaket: 1000 adet/kutu','UV-A ve UV-B direnci\r\nRenk stabilitesi\r\nHafif ve kolay montaj\r\nÇevre dostu malzeme\r\n','','','Plastik Deck Klipsi, Deck Klipsi','[{\"q\":\"Plastik deck klipsi nedir?\",\"a\":\"Plastik deck klipsi, deck kaplama tahtalarını sabitlemek için kullanılan, vidaların görünmesini engelleyen gizli montaj elemanıdır.\"},{\"q\":\"Plastik klipsler dış mekânda dayanıklı mı?\",\"a\":\"Evet, UV ışınlarına ve hava koşullarına dayanıklı özel plastikten üretilir, uzun ömürlü kullanım sağlar.\"},{\"q\":\"Hangi deck türleriyle uyumludur?\",\"a\":\"Genellikle kompozit deck ve bazı ahşap deck sistemleriyle uyumludur. Ürün ölçülerine göre kontrol edilmesi önerilir.\\n\"}]','[{\"name\":\"Hazırlık\",\"text\":\"Montaj öncesi küçük bir alanda deneme yaparak klipslerin uyumunu ve aralık ölçülerini kontrol edin.\"},{\"name\":\"Klipslerin Yerleştirilmesi\",\"text\":\"Klipsleri alt konstrüksiyona sabitleyin ve deck tahtalarını klipslerin arasına dikkatlice yerleştirin.\"},{\"name\":\"Sabitleme ve Kontrol\",\"text\":\"Tüm vidaları sıkın ve yüzeyin düzgünlüğünü kontrol ederek montajı tamamlayın.\"}]','uv-dayanimli-plastik-deck-klipsi',NULL,NULL,'',''),(84,8,'en','UV-Resistant Plastic Deck Clip','UV-stabilized polymer deck clip providing maximum resistance against sunlight.','The UV-Resistant Plastic Deck Clip is a plastic deck clip system manufactured with special UV stabilizer additives, offering superior resistance to sunlight.<br><br>It does not fade, become brittle, or deform even after years of direct sun exposure. Ideal for all outdoor deck applications.<br><br>Its lightweight structure ensures easy transportation and installation. Made from eco-friendly materials and is recyclable.','Material: UV-Stabilized HDPE Polymer<br>Size: Standard<br>UV Resistance: Max.<br>Color: Black / Brown<br>Package: 1000 units/box','UV-A and UV-B resistance<br>Color stability<br>Lightweight and easy installation<br>Eco-friendly material','','','Plastic Deck Clip, Deck Clip','[{\"q\":\"What is a plastic deck clip?\",\"a\":\"A plastic deck clip is a hidden mounting accessory used to secure deck boards, preventing screws from being visible.\"},{\"q\":\"Are plastic clips durable for outdoor use?\",\"a\":\"Yes, they are made from special UV and weather-resistant plastic, ensuring long-lasting performance.\"},{\"q\":\"Which deck types are compatible with these clips?\",\"a\":\"They are generally compatible with composite decking and some wooden deck systems. It is recommended to check product dimensions for compatibility.\"}]','[{\"name\":\"Preparation\",\"text\":\"Before installation, test the clips in a small area to verify compatibility and spacing measurements.\"},{\"name\":\"Placing the Clips\",\"text\":\"Secure the clips to the substructure and carefully place the deck boards between the clips.\"},{\"name\":\"Securing and Inspection\",\"text\":\"Tighten all screws and check the surface for evenness to complete the installation.\"}]','uv-resistant-plastic-deck-clip',NULL,NULL,'',''),(85,8,'ar','كليب أرضية بلاستيكي مقاوم للأشعة فوق البنفسجية','كليب أرضية بلاستيكي مُثبت ضد الأشعة فوق البنفسجية يوفر أقصى مقاومة لأشعة الشمس.','كليب أرضية بلاستيكي مقاوم للأشعة فوق البنفسجية هو نظام كليب أرضية بلاستيكي مُنتج بإضافات مثبتة خاصة ضد الأشعة فوق البنفسجية، ويظهر مقاومة فائقة لأشعة الشمس.\r\n\r\nلا يتغير لونه أو يصبح هشاً أو يتشوه حتى بعد سنوات من التعرض المباشر لأشعة الشمس. مثالي لجميع تطبيقات الأرضيات الخارجية.\r\n\r\nبفضل هيكله الخفيف، يسهل نقله وتركيبه. مصنوع من مواد صديقة للبيئة وقابل لإعادة التدوير.','المادة: بوليمر HDPE المثبت ضد الأشعة فوق البنفسجية\r\nالحجم: قياسي\r\nمقاومة الأشعة فوق البنفسجية: أقصى حد\r\nاللون: أسود / بني\r\nالتعبئة: 1000 قطعة/صندوق','مقاومة للأشعة فوق البنفسجية (UV-A و UV-B)\r\nثبات اللون\r\nخفيف وسهل التركيب\r\nمادة صديقة للبيئة','','','كليب أرضية بلاستيكي، كليب أرضية','[{\"q\":\"ما هو كليب الأرضيات البلاستيكي؟\",\"a\":\"كليب الأرضيات البلاستيكي هو عنصر تثبيت مخفي يستخدم لتثبيت ألواح تغطية الأرضيات دون ظهور البراغي.\"},{\"q\":\"هل الكليبات البلاستيكية متينة للاستخدام الخارجي؟\",\"a\":\"نعم، تُصنع من بلاستيك خاص مقاوم للأشعة فوق البنفسجية وظروف الطقس، مما يوفر استخداماً طويل الأمد.\"},{\"q\":\"مع أي أنواع الأرضيات يتوافق؟\",\"a\":\"يتوافق عادةً مع أنظمة الأرضيات المركبة وبعض أنظمة الأرضيات الخشبية. يُنصح بالتحقق من أبعاد المنتج.\"}]','[{\"name\":\"التحضير\",\"text\":\"قبل التركيب، قم بإجراء اختبار في مساحة صغيرة للتحقق من توافق الكليبات وأبعاد الفواصل.\"},{\"name\":\"وضع الكليبات\",\"text\":\"قم بتثبيت الكليبات على الهيكل السفلي وضع ألواح الأرضيات بعناية بين الكليبات.\"},{\"name\":\"التثبيت والفحص\",\"text\":\"قم بشد جميع البراغي وتحقق من استواء السطح لإكمال التركيب.\"}]','',NULL,NULL,'',''),(104,14,'tr','Plastik Deck Klips','Dayanıklı plastik deck klipsleri ile ahşap veya kompozit decklerinizi güvenle monte edin. Suya, neme ve UV ışınlarına karşı yüksek direnç sunan bu klipsler, uzun ömürlü ve estetik bir montaj çözümü sağlar.','Plastik deck klipsleri, açık hava deck projeleriniz için ideal bir montaj çözümüdür. Ahşap veya kompozit deck malzemelerinin birbirine güvenli ve düzgün bir şekilde bağlanmasını sağlayan bu klipsler, profesyonel ve estetik bir görünüm elde etmenize yardımcı olur. Yüksek kaliteli plastik malzemeden üretilen deck klipsleri, suya, neme, küf oluşumuna ve UV ışınlarına karşı dayanıklıdır. Bu sayede uzun yıllar boyunca deformasyon veya renk solması yaşamadan kullanabilirsiniz. Kolay ve hızlı montaj imkanı sunan plastik deck klipsleri, vida delikleri sayesinde deck tahtalarının sabitlenmesini kolaylaştırır. Ayrıca, gizli montaj özelliği ile estetik bir görünüm sağlar ve tahtalar arasında eşit aralıklar bırakarak profesyonel bir işçilik sunar. Hem ev bahçeleri hem de ticari alanlar için uygun olan bu klipsler, farklı renk ve boyut seçenekleri ile çeşitli deck projelerine uyum sağlar. Dayanıklılığı ve kullanım kolaylığı ile öne çıkan plastik deck klipsleri, deck montajında vazgeçilmez bir üründür.','Malzeme: UV Stabilize HDPE Polimer\r\nBoyut: Standart\r\nUV Direnci: Max.\r\nRenk: Siyah / Kahverengi\r\nPaket: 1000 adet/kutu','','','','plastik deck klips, deck klipsi, ahşap deck klips, kompozit deck klips, gizli montaj klips, suya dayanıklı deck klips, UV dirençli klips, deck montaj aksesuarı, açık hava deck klips, bahçe deck klips, ekonomik deck klips, hızlı montaj klips, dayanıklı deck klips, estetik deck montajı','','','plastik-deck-klips',NULL,NULL,'',''),(105,14,'en','Plastic Deck Clips','Securely install your wooden or composite decks with durable plastic deck clips. These clips offer high resistance to water, moisture, and UV rays, providing a long-lasting and aesthetic mounting solution.','Plastic deck clips are the ideal mounting solution for your outdoor deck projects. These clips ensure that wooden or composite deck materials are securely and evenly connected, helping you achieve a professional and aesthetic appearance. Made from high-quality plastic material, deck clips are resistant to water, moisture, mold, and UV rays. This ensures that you can use them for many years without experiencing deformation or color fading. Plastic deck clips offer easy and quick installation, and the pre-drilled screw holes facilitate the fastening of deck boards. Additionally, the hidden mounting feature provides an aesthetic appearance and ensures even spacing between boards for a professional finish. Suitable for both residential gardens and commercial areas, these clips come in various colors and sizes to fit different deck projects. Renowned for their durability and ease of use, plastic deck clips are an indispensable product for deck installation.','Material: UV-Stabilized HDPE Polymer\r\nSize: Standard\r\nUV Resistance: Max.\r\nColor: Black / Brown\r\nPackage: 1000 units/box','','','','plastic deck clip, deck clip, wooden deck clip, composite deck clip, hidden mounting clip, water-resistant deck clip, UV-resistant clip, deck mounting accessory, outdoor deck clip, garden deck clip, economical deck clip, quick installation clip, durable deck clip, aesthetic deck installation','','','plastic-deck-clips',NULL,NULL,'',''),(106,14,'ar','كليپس بلاستيكي للأرضيات الخشبية','قم بتركيب أرضياتك الخشبية أو المركبة بأمان باستخدام الكليپس البلاستيكي المتين للأرضيات. توفر هذه الكليپسات مقاومة عالية ضد الماء والرطوبة وأشعة UV، مما يوفر حل تركيب طويل الأمد وجمالي.','تعتبر الكليپسات البلاستيكية للأرضيات حل تركيب مثالي لمشاريع الأرضيات الخارجية. تضمن هذه الكليپسات ربط مواد الأرضيات الخشبية أو المركبة ببعضها البعض بطريقة آمنة ومتساوية، مما يساعدك على تحقيق مظهر احترافي وجمالي. مصنوعة من مواد بلاستيكية عالية الجودة، تتميز الكليپسات البلاستيكية للأرضيات بمقاومتها للماء والرطوبة والعفن وأشعة UV. وبفضل ذلك، يمكنك استخدامها لسنوات طويلة دون تعرضها للتشوه أو بهتان اللون. توفر الكليپسات البلاستيكية للأرضيات تركيبًا سهلًا وسريعًا بفضل فتحات البراغي التي تسهل تثبيت ألواح الأرضيات. كما أنها تتميز بخاصية التركيب الخفي التي تضمن مظهرًا جماليًا وتترك مسافات متساوية بين الألواح لتقديم عمل احترافي. مناسبة لكل من الحدائق المنزلية والمساحات التجارية، تأتي هذه الكليپسات بمجموعة متنوعة من الألوان والأحجام لتناسب مختلف مشاريع الأرضيات. بفضل متانتها وسهولة استخدامها، تُعد الكليپسات البلاستيكية للأرضيات منتجًا لا غنى عنه في تركيب الأرضيات.','المادة: بوليمر HDPE المثبت ضد الأشعة فوق البنفسجية\r\nالحجم: قياسي\r\nمقاومة الأشعة فوق البنفسجية: قصوى\r\nاللون: أسود / بني\r\nالتعبئة: 1000 قطعة/صندوق','','','','كليپس بلاستيكي للأرضيات, كليپس أرضيات, كليپس أرضيات خشبية, كليپس أرضيات مركبة, كليپس تركيب خفي, كليپس مقاوم للماء, كليپس مقاوم للأشعة فوق البنفسجية, ملحقات تركيب الأرضيات, كليپس أرضيات خارجية, كليپس أرضيات حدائق, كليپس أرضيات اقتصادي, كليپس تركيب سريع, كليپس أرضيات متين, تركيب أرضيات جمالي','[]','','',NULL,NULL,'',''),(194,15,'tr','Cam Balkon Hareketli Boynuz','Cam balkon sistemleri için yüksek kaliteli hareketli boynuz. Dayanıklı yapısı ve estetik tasarımı ile güvenli ve şık bir kullanım sunar.','Cam balkon sistemlerinizde mükemmel bir uyum ve işlevsellik arayışındaysanız, hareketli boynuz ürünümüz tam size göre. Plastikten üretilen bu hareketli boynuz, uzun ömürlü kullanım ve dayanıklılık sağlar. Kolay montaj imkanı ile zamandan tasarruf etmenizi sağlarken, estetik görünümü ile balkonunuzun modern ve şık bir görünüme kavuşmasını sağlar. Hareketli yapısı sayesinde cam panellerinizin kolayca açılıp kapanmasına olanak tanır, böylece balkonunuzu kullanırken maksimum konfor elde edersiniz. Hem iç hem de dış mekanlarda güvenle kullanılabilen bu ürün, her türlü hava koşuluna karşı dayanıklıdır. Cam balkon sisteminizin güvenliğini ve işlevselliğini artırmak için ideal bir tercihtir.','Malzeme: Plastik\r\nRenk: Siyah ve Beyaz. \r\nBoyutlar: Standart \r\nAğırlık: 250 gram. \r\nMontaj Tipi: Vida ile sabitleme. \r\nKullanım Alanı: Cam balkon sistemleri. \r\nDayanıklılık: Su ve pas direnci. \r\nUyumluluk: Çeşitli cam kalınlıkları ile uyumlu.','Plastik ürün yüksek dayanıklılık sunar. Estetik ve modern tasarımı ile balkonunuza şıklık katar. Kolay montaj imkanı ile zamandan tasarruf sağlar. Hareketli yapısı sayesinde cam panellerin kolayca açılıp kapanmasını sağlar. İç ve dış mekanlarda güvenle kullanılabilir. Her türlü hava koşuluna karşı dayanıklıdır. Çeşitli cam kalınlıkları ile uyumludur. Uzun ömürlü kullanım garantisi sunar.','','','cam balkon hareketli boynuz, paslanmaz çelik boynuz, balkon boynuz, cam balkon aksesuarları, dayanıklı boynuz, estetik boynuz, balkon dekorasyon, cam balkon sistemleri, hareketli boynuz, balkon güvenlik aksesuarları','[{\"q\":\"Cam Balkon Hareketli Boynuz Kolisinde Kaç Adet Var?\",\"a\":\"200 Adet\"}]','[{\"name\":\"Kargo Fiyata Dahil mi?\",\"text\":\"Evet\"}]','cam-balkon-hareketli-boynuz','Cam Balkon Hareketli Boynuz','Lojistik','200 Adet - Kargo Dahildir.',''),(195,15,'en','Sliding Horn for Glass Balcony','High-quality sliding horn for glass balcony systems. Offers safe and stylish usage with its durable structure and aesthetic design.','If you are looking for perfect fit and functionality in your glass balcony systems, our movable horn product is just right for you. This movable horn, manufactured from plastic, ensures long-lasting use and durability. While saving you time with its easy installation, its aesthetic appearance gives your balcony a modern and elegant look. Thanks to its movable structure, it allows your glass panels to open and close easily, providing maximum comfort while using your balcony. This product, which can be safely used in both indoor and outdoor spaces, is resistant to all weather conditions. It is an ideal choice to enhance the safety and functionality of your glass balcony system.','Material: Plastic\r\nColor: Black and White\r\nDimensions: Standard\r\nWeight: 250 grams\r\nMounting Type: Screw fixing\r\nApplication Area: Glass balcony systems\r\nDurability: Water and rust resistance\r\nCompatibility: Compatible with various glass thicknesses','The movable horn is a stainless steel accessory used in glass balcony systems, enabling smooth and secure opening and closing of glass panels. Its structure compatible with various glass thicknesses ensures easy installation. With water and rust resistance, it guarantees long-lasting durability.','','','sliding horn for glass balcony, stainless steel horn, balcony horn, glass balcony accessories, durable horn, aesthetic horn, balcony decoration, glass balcony systems, sliding horn, balcony safety accessories','[{\"q\":\"How Many Sliding Horns Are in a Glass Balcony Sliding Horn Set?\",\"a\":\"200 Units\"}]','[{\"name\":\"Is Shipping Included in the Price?\",\"text\":\"Yes\"}]','sliding-horn-for-glass-balcony','Sliding Horn for Glass Balcony','Logistics','200 Pieces - Shipping Included.',''),(196,15,'ar','قرن متحرك لشرفات الزجاج','قرن متحرك عالي الجودة لأنظمة شرفات الزجاج. يوفر استخداماً آمناً وأنيقاً بفضل هيكله المتين وتصميمه الجمالي.','إذا كنتم تبحثون عن التوافق المثالي والوظائف المتميزة في أنظمة الشرفات الزجاجية لديكم، فإن منتج الذراع المتحرك الخاص بنا هو الخيار الأمثل لكم. هذا الذراع المتحرك المصنوع من البلاستيك يضمن استخدامًا طويل الأمد ومتانة عالية. فهو يوفر لكم الوقت بفضل سهولة التركيب، كما يمنح شرفتكم مظهرًا عصريًا وأنيقًا بفضل تصميمه الجمالي. بفضل بنيته المتحركة، يتيح فتح وإغلاق الألواح الزجاجية بسهولة، مما يوفر لكم أقصى درجات الراحة أثناء استخدام الشرفة. يمكن استخدام هذا المنتج بأمان في الأماكن الداخلية والخارجية على حد سواء، وهو مقاوم لجميع الظروف الجوية. إنه الخيار المثالي لتعزيز سلامة ووظائف نظام الشرفة الزجاجية لديكم.','المادة: بلاستيك\r\nاللون: أسود وأبيض\r\nالأبعاد: قياسي\r\nالوزن: 250 غرام\r\nنوع التركيب: تثبيت بالبراغي\r\nمجال الاستخدام: أنظمة الشرفات الزجاجية\r\nالمتانة: مقاومة للماء والصدأ\r\nالتوافق: متوافق مع مختلف سماكات الزجاج','مصنوع من الفولاذ المقاوم للصدأ ويوفر متانة عالية. يضفي التصميم الجمالي والحديث أناقة على شرفاتك. يوفر سهولة التركيب ويوفر الوقت. يسمح الهيكل المتحرك بفتح وإغلاق ألواح الزجاج بسهولة. يمكن استخدامه بأمان في الأماكن الداخلية والخارجية. مقاوم لجميع الظروف الجوية. متوافق مع مختلف سماكات الزجاج. يوفر ضمان استخدام طويل الأمد.','','','قرن متحرك لشرفات الزجاج، قرن من الفولاذ المق