INSERT INTO `products` VALUES (1,'Metal Deck Klips Pro 316','metal-deck-klips-pro-316','metal-deck-klips','/uploads/products/69d6703d4f021_Metal-Deck-klips.jpg','/uploads/products/69d7d0e378706_Metal-Deck-klips-1.jpg,/uploads/products/69d7d2c2b495a_Metal-Deck-klips-1.jpg','Paslanmaz 316 çelikten üretilen, deniz ortamına dayanıklı profesyonel deck klips sistemi.','Metal Deck Klips Pro 316, özellikle kıyı şeridi ve denize yakın alanlarda kullanım için tasarlanmış, AISI 316 paslanmaz çelik alaşımından üretilmiş premium deck montaj klips sistemidir.\r\n\r\nYüksek tuz ve nem direnci sayesinde yıllarca bakım gerektirmez. Görünmez montaj sistemiyle estetik yüzey sağlar.\r\n\r\nProfesyonel projelerde güvenle tercih edilen, 10 yıl garantili ürünümüz ile deck sisteminiz dayanıklılık ve şıklığı bir arada sunar.','Malzeme: AISI 316 Paslanmaz Çelik\r\nBoyut: 52mm x 28mm x 3mm\r\nKaplama: Elektrolitik Parlatma\r\nDayanım: -40°C ile +200°C arası\r\nISO Sertifika: 9001:2015\r\nPaket: 100 adet/kutu','Korozyona karşı maksimum direnç\r\nDeniz ortamı sertifikası\r\nGörünmez montaj sistemi\r\n10 yıl ürün garantisi\r\nKolaylaştırılmış kurulum\r\nTüm deck panellerine uyumlu',NULL,'TRY','in_stock','active',2,'','','','2026-04-04 20:43:01','2026-05-16 13:19:44','','','[]','Metal Deck Klips Pro 316','Metal Deck Klips Pro 316','Professional deck clip solution.','مشبك سطح احترافي.','Premium grade deck mounting solution for professional exterior applications. High durability and aesthetic finish guaranteed.','حل تركيب أسطح من الدرجة الممتازة للتطبيقات الخارجية الاحترافية. متانة عالية ولمسة جمالية مضمونة.','Grade: Professional\nDurability: 10/10','الدرجة: محترف\nالمتانة: 10/10','- High structural strength\n- UV stabilization\n- Corrosion resistant coating\n- Hidden fastener design','- قوة هيكلية عالية\n- استقرار الأشعة فوق البنفسجية\n- طلاء مقاوم للتآكل\n- تصميم قفل مخفي','',NULL,NULL,NULL,NULL,'','',1),(2,'Plastik Deck Klips UV-Pro','plastik-deck-klips-uv-pro','plastik-deck-klips','/uploads/products/69d913299bab9_plastik-deck-klips-2.jpg','','UV dayanımlı yüksek yoğunluklu polimer yapısıyla üstün performans sunan deck klips sistemi.','Plastik Deck Klips UV-Pro, güneş ışınlarına karşı maksimum dayanıklılık için özel UV stabilizatör katkı maddesiyle üretilen, yüksek yoğunluklu polimer bazlı bir deck montaj sistemidir.\r\n\r\nTüm dış mekan uygulamaları için idealdir. Çevre dostu malzemeden üretilmiş olup, geri dönüşüme uygundur.\r\n\r\n15 yıl renk stabilitesi garantisi ile uzun ömürlü kullanım sağlar.','Malzeme: UV Stabilize HDPE Polimer\r\nBoyut: STANDART\r\nRenk: Kahverengi\r\nPaket: 1000 adet/kutu','UV-A ve UV-B ışınlarına tam direnç\r\nÇevre dostu malzeme\r\nKolay kurulum\r\nDarbe ve çizilme direnci\r\nHafif ve ekonomik',NULL,'TRY','in_stock','active',3,'','','DECK Klips, Plastik Deck Klips UV-Pro, Plastik Deck Klips, Deck Klips Plastik','2026-04-04 20:43:01','2026-05-16 13:19:44','','','[]','Premium Plastic Deck Klips UV-Pro','بلاستيك فاخر Deck Klips UV-Pro','Professional deck clip solution.','مشبك سطح احترافي.','Premium grade deck mounting solution for professional exterior applications. High durability and aesthetic finish guaranteed.','حل تركيب أسطح من الدرجة الممتازة للتطبيقات الخارجية الاحترافية. متانة عالية ولمسة جمالية مضمونة.','Grade: Professional\nDurability: 10/10','الدرجة: محترف\nالمتانة: 10/10','- High structural strength\n- UV stabilization\n- Corrosion resistant coating\n- Hidden fastener design','- قوة هيكلية عالية\n- استقرار الأشعة فوق البنفسجية\n- طلاء مقاوم للتآكل\n- تصميم قفل مخفي','',NULL,NULL,NULL,NULL,'','',1),(3,'Gizli Montaj Deck Klipsi','gizli-montaj-deck-klipsi','plastik-deck-klips','/uploads/products/69d68ce560cd1_plastik-deck-klips-modelleri1.jpg','/uploads/products/69d68ce5620fc_Plastik-deck-klips-1.jpg','Ahşap ve kompozit deck panellerde görünmez montaj sağlayan plastik klips montaj sistemi.','Gizli Montaj Deck Klipsi, ahşap ve kompozit deck uygulamalarında vidaların görünmesini istemeyen profesyoneller için tasarlanmıştır. Kullanım amacına uygun plastikten üretilen deck klips uzun ömürlü kullanım sunar.\r\n\r\nDeck panellerinin arasına gizlenen özel tasarımı sayesinde estetik bir yüzey elde edilir. Kolay montajı ile işçilik süresini kısaltır.\r\n\r\nHem iç hem dış mekan uygulamalarında güvenle kullanılabilir. ','Malzeme: Plastik\r\nBoyut: Görselde inceleyiniz.\r\nUyumlu Deck Kalınlığı: 18-25mm\r\nPaket: 1000 adet/kutu\r\n','Gizli montaj sistemi\r\nPlastik yapı\r\nKolay kurulum\r\nStandart deck tiplerine uyumlu',NULL,'TRY','in_stock','active',1,'','','Deck Klips, Deck Klips Plastik','2026-04-05 16:28:20','2026-05-16 13:19:44','','','[]','Gizli Montaj Deck Clip','Gizli Montaj Deck مشبك','Professional deck clip solution.','مشبك سطح احترافي.','Premium grade deck mounting solution for professional exterior applications. High durability and aesthetic finish guaranteed.','حل تركيب أسطح من الدرجة الممتازة للتطبيقات الخارجية الاحترافية. متانة عالية ولمسة جمالية مضمونة.','Grade: Professional\nDurability: 10/10','الدرجة: محترف\nالمتانة: 10/10','- High structural strength\n- UV stabilization\n- Corrosion resistant coating\n- Hidden fastener design','- قوة هيكلية عالية\n- استقرار الأشعة فوق البنفسجية\n- طلاء مقاوم للتآكل\n- تصميم قفل مخفي','',NULL,NULL,NULL,NULL,'','',1),(4,'Paslanmaz Çelik Deck Sabitleme Klipsi','paslanmaz-celik-deck-sabitleme-klipsi','metal-deck-klips','/uploads/products/69da0da06f96c_Deck-Klips-Paslanmaz.jpg','','Yüksek korozyon direncine sahip, ağır yük kapasiteli paslanmaz çelik deck sabitleme klipsi.','Paslanmaz Çelik Deck Sabitleme Klipsi, yüksek korozyon direnci ve ağır yük taşıma kapasitesi ile endüstriyel ve ticari deck projeleri için idealdir.\r\n\r\nAISI 316 paslanmaz çelik alaşımından üretilen bu klips, deniz ortamları ve yüksek nemli bölgelerde bile paslanma yapmaz.\r\n\r\nÖzel diş yapısı sayesinde deck panelini sabitlerken kayma ve gevşeme yapmaz. Profesyonel montaj ekiplerinin tercih ettiği güvenilir bir çözümdür.','Malzeme: AISI 316 Paslanmaz Çelik\r\nBoyut: 40mm x 40mm x 1.5mm\r\nPaket: 1000 adet/kutu','AISI 316 paslanmaz çelik\r\nYüksek taşıma kapasitesi\r\nDeniz ortamı uyumlu\r\nKayma ve gevşeme yapmaz.',NULL,'TRY','in_stock','active',10,'','','Paslanmaz Çelik Deck Klips, Deck Klips, Paslanmaz Deck Klips','2026-04-05 16:28:20','2026-05-16 13:19:44','','','[]','Stainless Steel Deck Sabitleme Clip','ستانلس ستيل Deck Sabitleme مشبك','Professional deck clip solution.','مشبك سطح احترافي.','Premium grade deck mounting solution for professional exterior applications. High durability and aesthetic finish guaranteed.','حل تركيب أسطح من الدرجة الممتازة للتطبيقات الخارجية الاحترافية. متانة عالية ولمسة جمالية مضمونة.','Grade: Professional\nDurability: 10/10','الدرجة: محترف\nالمتانة: 10/10','- High structural strength\n- UV stabilization\n- Corrosion resistant coating\n- Hidden fastener design','- قوة هيكلية عالية\n- استقرار الأشعة فوق البنفسجية\n- طلاء مقاوم للتآكل\n- تصميم قفل مخفي','',NULL,NULL,NULL,NULL,'','',1),(5,'Yan Gizli Bağlantı Deck Klipsi','yan-gizli-baglanti-deck-klipsi','metal-deck-klips','/uploads/products/69d947a057161_KompozitTDeckKlips8mm.jpg','','Deck panellerinin yan kenarlarından gizli bağlantı sağlayan profesyonel metal klips.','Yan Gizli Bağlantı Deck Klipsi, deck panellerinin yan kenarlarından birbirine bağlanmasını sağlayan özel tasarımlı bir metal klips sistemidir.\r\n\r\nPaneller arasında eşit boşluk bırakarak doğal ahşap genleşmesine olanak tanır. Bu sayede deck yüzeyinde çatlama ve eğilme önlenir.\r\n\r\nPaslanmaz çelik gövdesi ve ergonomik tasarımı ile hızlı ve güvenli montaj imkanı sunar. Teras, havuz kenarı ve balkon uygulamalarında idealdir.','Malzeme: Sac  + Kaplama\r\nBoyut: STANDART\r\nPaket: 1000 adet/kutu\r\n','Yan gizli bağlantı\r\nDoğal genleşme payı\r\nEşit panel aralığı\r\nHızlı montaj\r\nDış mekan uyumlu',NULL,'TRY','in_stock','active',3,'','','DECK Klips, T DECK Klips, 8mm DECK Klips','2026-04-05 16:28:20','2026-05-16 13:19:44','','','[]','Yan Gizli Bağlantı Deck Clip','Yan Gizli Bağlantı Deck مشبك','Professional deck clip solution.','مشبك سطح احترافي.','Premium grade deck mounting solution for professional exterior applications. High durability and aesthetic finish guaranteed.','حل تركيب أسطح من الدرجة الممتازة للتطبيقات الخارجية الاحترافية. متانة عالية ولمسة جمالية مضمونة.','Grade: Professional\nDurability: 10/10','الدرجة: محترف\nالمتانة: 10/10','- High structural strength\n- UV stabilization\n- Corrosion resistant coating\n- Hidden fastener design','- قوة هيكلية عالية\n- استقرار الأشعة فوق البنفسجية\n- طلاء مقاوم للتآكل\n- تصميم قفل مخفي','',NULL,NULL,NULL,NULL,'','',1),(6,'Profesyonel Deck Montaj Klipsi','profesyonel-deck-montaj-klipsi','metal-deck-klips','/uploads/products/69d67aa7f39ea_KompozitDeckKlips7mm.jpg','','Profesyonel uygulamalar için tasarlanmış, yüksek dayanımlı metal deck montaj klipsi.','Profesyonel Deck Montaj Klipsi, büyük ölçekli deck projeleri ve profesyonel montaj ekipleri için geliştirilmiş üstün performanslı bir üründür.\r\n\r\nÇift kilit mekanizması ile deck panelini alt yapıya sıkıca sabitler. Titreşim ve darbe dayanımı yüksektir.\r\n\r\nÖzel yüzey işlemi sayesinde çizilme ve aşınmaya karşı dirençlidir. Tüm metal ve ahşap alt yapılarla uyumludur.\r\n\r\nTicari projeler, restoran terasları ve otel havuz alanları için ideal bir çözümdür.','Malzeme: Sertleştirilmiş Sac + Kaplama\r\nBoyut: 4,5Cm x 4,5Cm x 1,5Cm\r\nKilit Mekanizması: Çift Kilit\r\nPaket: 1000 adet/kutu\r\n','Çift kilit mekanizması\r\nYüksek darbe dayanımı\r\nÇizilme direnci\r\nTicari kullanım uyumlu\r\nProfesyonel montaj',NULL,'TRY','in_stock','active',4,'','','','2026-04-05 16:28:20','2026-05-16 13:19:44','','','[]','Profesyonel Deck Montaj Clip','Profesyonel Deck Montaj مشبك','Professional deck clip solution.','مشبك سطح احترافي.','Premium grade deck mounting solution for professional exterior applications. High durability and aesthetic finish guaranteed.','حل تركيب أسطح من الدرجة الممتازة للتطبيقات الخارجية الاحترافية. متانة عالية ولمسة جمالية مضمونة.','Grade: Professional\nDurability: 10/10','الدرجة: محترف\nالمتانة: 10/10','- High structural strength\n- UV stabilization\n- Corrosion resistant coating\n- Hidden fastener design','- قوة هيكلية عالية\n- استقرار الأشعة فوق البنفسجية\n- طلاء مقاوم للتآكل\n- تصميم قفل مخفي','',NULL,NULL,NULL,NULL,'','',1),(7,'Yüksek Dayanımlı Deck Bağlantı Klipsi','yuksek-dayanimli-deck-baglanti-klipsi','metal-deck-klips','/uploads/products/69d92e09778e6_Kalin-Deck-Klips.jpg','','Ekstra kalın yapısıyla yüksek yük taşıma kapasitesine sahip dayanıklı deck bağlantı klipsi.','Yüksek Dayanımlı Deck Bağlantı Klipsi, ekstra kalın metal yapısı ve güçlendirilmiş tasarımı ile ağır yük taşıma gerektiren deck projeleri için üretilmiştir.\r\n\r\n3mm kalınlığındaki gövdesi sayesinde standart klipslere göre %40 daha fazla yük taşır. Endüstriyel alanlar, araç geçişli deck platformları ve ticari kullanım için uygundur.\r\n\r\nPaslanmaz çelik bağlantı noktaları ve korozyon önleyici kaplama ile uzun ömürlü kullanım sağlar. Zorlu hava koşullarına karşı test edilmiştir.','Malzeme: Sertleştirilmiş Sac\r\nBoyut: 4,5cm x 4,5cm x 2mm\r\nPaket: 500 adet/kutu\r\n','Ekstra kalın 2mm sac\r\n%40 daha yüksek yük kapasitesi\r\nZorlu hava koşullarına dayanıklı\r\nEndüstriyel kullanım',NULL,'TRY','in_stock','active',5,'','','Yüksek Dayanımlı Deck Bağlantı Klipsi, Deck Bağlantı Klipsi, Deck Klipsi, Kalın Deck Klipsi','2026-04-05 16:28:20','2026-05-16 13:19:44','','','[]','Yüksek Dayanımlı Deck Bağlantı Clip','Yüksek Dayanımlı Deck Bağlantı مشبك','Professional deck clip solution.','مشبك سطح احترافي.','Premium grade deck mounting solution for professional exterior applications. High durability and aesthetic finish guaranteed.','حل تركيب أسطح من الدرجة الممتازة للتطبيقات الخارجية الاحترافية. متانة عالية ولمسة جمالية مضمونة.','Grade: Professional\nDurability: 10/10','الدرجة: محترف\nالمتانة: 10/10','- High structural strength\n- UV stabilization\n- Corrosion resistant coating\n- Hidden fastener design','- قوة هيكلية عالية\n- استقرار الأشعة فوق البنفسجية\n- طلاء مقاوم للتآكل\n- تصميم قفل مخفي','',NULL,NULL,NULL,NULL,'','',1),(8,'UV Dayanımlı Plastik Deck Klipsi','uv-dayanimli-plastik-deck-klipsi','plastik-deck-klips','/uploads/products/69d90ef54479d_plastik-deck-klips.jpg','','Güneş ışınlarına karşı maksimum dayanıklılık sağlayan UV stabilize polimer deck klipsi.','UV Dayanımlı Plastik Deck Klipsi, özel UV stabilizatör katkı maddeleriyle üretilmiş, güneş ışınlarına karşı üstün direnç gösteren bir plastik deck klips sistemidir.\r\n\r\nYıllarca doğrudan güneş altında bile renk solması, kırılganlaşma veya deformasyon yapmaz. Tüm dış mekan deck uygulamaları için idealdir.\r\n\r\nHafif yapısı sayesinde kolay taşınır ve monte edilir. Çevre dostu malzemeden üretilmiş olup geri dönüşüme uygundur.','Malzeme: UV Stabilize HDPE Polimer\r\nBoyut: Standart\r\nUV Direnci: Max.\r\nRenk: Siyah / Kahverengi\r\nPaket: 1000 adet/kutu','UV-A ve UV-B direnci\r\nRenk stabilitesi\r\nHafif ve kolay montaj\r\nÇevre dostu malzeme\r\n',NULL,'TRY','in_stock','active',1,'','','Plastik Deck Klipsi, Deck Klipsi','2026-04-05 16:28:20','2026-05-16 13:19:44','','','[]','UV Dayanımlı Premium Plastic Deck Clip','UV Dayanımlı بلاستيك فاخر Deck مشبك','Professional deck clip solution.','مشبك سطح احترافي.','Premium grade deck mounting solution for professional exterior applications. High durability and aesthetic finish guaranteed.','حل تركيب أسطح من الدرجة الممتازة للتطبيقات الخارجية الاحترافية. متانة عالية ولمسة جمالية مضمونة.','Grade: Professional\nDurability: 10/10','الدرجة: محترف\nالمتانة: 10/10','- High structural strength\n- UV stabilization\n- Corrosion resistant coating\n- Hidden fastener design','- قوة هيكلية عالية\n- استقرار الأشعة فوق البنفسجية\n- طلاء مقاوم للتآكل\n- تصميم قفل مخفي','https://www.youtube.com/watch?v=po2-YGSkS7k&t=1s','[{\"q\":\"Plastik deck klipsi nedir?\",\"a\":\"Plastik deck klipsi, deck kaplama tahtalarını sabitlemek için kullanılan, vidaların görünmesini engelleyen gizli montaj elemanıdır.\"},{\"q\":\"