INSERT INTO `timeline` VALUES (1,'2012','Kuruluş','DECK Klips, deck klips üretimi ve satışı için faaliyetlerine başladı..','/uploads/timeline/timeline_1777119659_69ecb1abc8cc9.jpg',1,'active','2026-04-04 20:43:02','2026-04-25 12:20:59','Foundation','DECK Clips started its operations for the production and sale of deck clips.','التأسيس','بدأت DECK CLIPS عملياتها في إنتاج وبيع مشابك الديك.'),(2,'2015','Büyüme','Türkiye genelinde 50+ bayi ağına ulaşıldı.','/uploads/timeline/timeline_1776949348_69ea18642ffe5.jpg',2,'active','2026-04-04 20:43:02','2026-04-25 11:56:06','Growth','A network of 50+ dealers has been reached across Turkey.','النمو','تم الوصول إلى شبكة تضم أكثر من 50 وكيلاً في جميع أنحاء تركيا.'),(3,'2018','Çatı Onarımı, Pergola Tamir | Tadilat Hizmetleri','Dayanıklılık, güvenlik ve uzun ömürlü performans sağlamak için profesyonel çatı ve pergola onarım hizmetleri sunuyoruz. Uzman ekibimiz hem konut hem de ticari dış mekan yapıları için güvenilir yenileme çözümleri sunar.','/uploads/timeline/timeline_1776949501_69ea18fd3799e.jpg',3,'active','2026-04-04 20:43:02','2026-04-25 11:58:47','Roof Repair, Pergola Repair | Renovation Services','We provide professional roof and pergola repair services to ensure durability, safety, and long-lasting performance. Our expert team delivers reliable renovation solutions for both residential and commercial outdoor structures.','إصلاح الأسقف وإصلاح البرجولات | خدمات الترميم','نقدم خدمات احترافية لإصلاح الأسقف والبرجولات لضمان المتانة والسلامة والأداء طويل الأمد. يوفر فريقنا المتخصص حلول ترميم موثوقة للمساحات الخارجية السكنية والتجارية.'),(4,'2020','Online Perakende ve Toptan Satış - www.ahtapotyapi.com','Deck Klips ve Farklı Alanlarda Kullanılabilen, Mobilya Bağlantı Elemanlarının E-ticaret platformu üzerinden online satışı başladı.','/uploads/timeline/timeline_1777119193_69ecafd9adfcc.jpg',4,'active','2026-04-04 20:43:02','2026-04-25 12:13:13','Online Retail and Wholesale - www.ahtapotyapi.com','The online sales of deck clips and furniture fastening components that can be used in various applications have started through the e-commerce platform.','البيع بالتجزئة والجملة عبر الإنترنت - www.ahtapotyapi.com','بدأت مبيعات مشابك الديك وعناصر ربط الأثاث القابلة للاستخدام في مجالات متعددة عبر منصة التجارة الإلكترونية.'),(5,'2024','İhracat','Azerbaycan pazarlarına ihracata başlandı.','/uploads/timeline/timeline_1777119207_69ecafe792650.jpg',5,'active','2026-04-04 20:43:02','2026-04-25 12:13:27','Export','Exports to the Azerbaijan market have started.','التصدير','بدأ التصدير إلى سوق أذربيجان.'),(6,'2025','CAM BALKON AKSESUARLARI Tedarik ve Toptan Satışı Başladı.','Cam balkon aksesuarlarında toptan satış ve tedarik hizmeti başlamıştır. Geniş ürün yelpazemiz, uygun fiyatlarımız ve stoktan hızlı teslimat avantajımızla projelerinize değer katıyoruz. Bayilik ve iş birliği talepleriniz için bizimle iletişime geçin.','/uploads/timeline/timeline_1778928174_6a084a2e49326.webp',6,'active','2026-05-16 10:42:54','2026-05-16 10:42:54','GLASS BALKON ACCESSORIES Started in Supply and Wholesale.','We are now offering wholesale supply and distribution of glass balcony accessories. With a comprehensive product range, competitive pricing, and fast delivery from stock, we add value to your projects. Contact us for dealership and partnership opportunities.','بدأت شركة إكسسوارات الشرفات الزجاجية في مجال التوريد والبيع بالجملة.','تم إطلاق خدمات التوريد والبيع بالجملة لإكسسوارات الشرفات الزجاجية. نقدم مجموعة واسعة من المنتجات بأسعار تنافسية وتسليم سريع من المخزون لدعم مشاريعكم. تواصلوا معنا لفرص التعاون والوكالات التجارية.');
/*!40000 ALTER TABLE `timeline` ENABLE KEYS */;
UNLOCK TABLES;

